<span class="line"><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF">cat ~</span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2">/</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF">.ssh</span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2">/</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF">id_ed25519.pub | ssh wjjsn</span><span style="--shiki-light:#E45649;--shiki-dark:#E06C75">@pi5.local</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379"> "mkdir -p ~/.ssh &amp;&amp; cat &gt;&gt; ~/.ssh/authorized_keys"</span></span>
